// Convert file to base64
        function convertFileToBase64(file) {
            return new Promise((resolve, reject) => {
                const reader = new FileReader();
                reader.onloadend = () => resolve(reader.result);
                reader.onerror = reject;
                reader.readAsDataURL(file);
            });
        }

        // Create PDF with embedded image
        async function createPdfWithImage(base64Image) {
            const { PDFDocument } = PDFLib;
            const pdfDoc = await PDFDocument.create();
            const page = pdfDoc.addPage([600, 400]);
            const { width, height } = page.getSize();

            // Embed image
            const image = await pdfDoc.embedPng(base64Image);
            const imageDims = image.scale(0.5);

            // Draw image on page
            page.drawImage(image, {
                x: 50,
                y: height - imageDims.height - 50,
                width: imageDims.width,
                height: imageDims.height,
            });

            // Serialize the PDF to bytes
            const pdfBytes = await pdfDoc.save();

            // Download the PDF
            const blob = new Blob([pdfBytes], { type: 'application/pdf' });
            const url = URL.createObjectURL(blob);
            window.open(url);
        }

        // Event listeners
        document.getElementById('generatePdfButton').addEventListener('click', async () => {
            const fileInput = document.getElementById('fileInput');
            const file = fileInput.files[0];
            if (file) {
                try {
                    const base64Image = await convertFileToBase64(file);
                    await createPdfWithImage(base64Image);
                } catch (error) {
                    console.error('Error generating PDF:', error);
                }
            } else {
                alert('Please select an image file first.');
            }
        });


function showContent(contentId) {
  // Hide all content first
  document.querySelectorAll('.content').forEach(function(content) {
    content.style.display = 'none';
  });
  
  // Show the selected content
  document.getElementById(contentId).style.display = 'block';
}
